import {
	Component,
	Element,
	Event,
	EventEmitter,
	Host,
	Prop,
	State,
	h,
} from "@stencil/core";
import {
	DRAGGABLE_ARIA,
	DraggableKeyboardHandler,
	applyGrabStateClasses,
	removeGrabStateClasses,
} from "./draggable-a11y";

import { dotsSix, statusNegative, trashSimple } from "../../../icons/index";
import getBootstrapConfig from "../../utils/getBootstrapConfig";

/**
 * @since 2.18.34
 * @status beta
 *
 * @description The `hbr-draggable` component is a wrapper that enables drag-and-drop functionality for its child elements. It supports multiple drag modes including copy, move, and reorder operations. Uses shadow DOM for proper framework compatibility - slotted content stays in the light DOM and won't re-render when the component updates.
 *
 * @slot - Used to pass in the draggable element.
 * @slot invalid-icon - Custom content for the invalid drop indicator icon. If not provided, a default "status-negative" icon is shown.
 * @slot overlay-handle - Custom content for the drag overlay handle. If not provided, a default drag icon is shown.
 * @slot delete-button - Custom content for the delete button (if `delete` prop is true). If not provided, a default trash icon button is shown.
 *
 * @part overlay - The drag overlay element that appears when dragging.
 * @part overlay-handle - The drag handle icon host within the overlay.
 * @part delete-button - The delete button base wrapper when `delete` is true.
 * @part delete-button-icon - The delete button icon wrapper when `delete` is true.
 * @part drop-indicator-invalid-tooltip - The invalid drop indicator tooltip host.
 * @part drop-indicator-invalid-tooltip__popup - The invalid drop indicator tooltip popup.
 * @part drop-indicator-invalid-tooltip__arrow - The invalid drop indicator tooltip arrow.
 * @part drop-indicator-invalid-icon - The invalid drop indicator icon base wrapper.
 */

@Component({
	tag: "hbr-draggable",
	styleUrl: "draggable.scss",
	shadow: true,
})
export class Draggable {
	@Element() host: HTMLElement;

	/** The drag operation type: 'copy', 'move' | 'reorder' */
	@Prop() operation: "copy" | "move" | "reorder" = "move";

	/** Unique identifier for this draggable item */
	@Prop({ reflect: true }) dragId: string;

	/** Data to transfer during drag (can be JSON) */
	@Prop() dragData: string;

	/** Whether to show the drag overlay with icon when dragging. Default is true. */
	@Prop({ reflect: true }) overlay = true;

	/** Whether to show the drag overlay icon. Only applies when `overlay` is true. */
	@Prop({ reflect: true }) overlayIcon = true;

	/** Whether to show a delete button on the drag overlay. Default is false. */
	@Prop() delete = false;

	/** i18n strings */
	@Prop() i18n: { rowFull: string } = { rowFull: "Row is full" };

	/** Event emitted when drag starts */
	@Event({ eventName: "hbr-drag-start" }) hbrDragStart: EventEmitter<{
		id: string;
		data: string;
		element: HTMLElement;
	}>;

	/** Event emitted when drag ends */
	@Event({ eventName: "hbr-drag-end" }) hbrDragEnd: EventEmitter<{
		id: string;
		success: boolean;
	}>;

	/** Event emitted when keyboard grab state changes */
	@Event({ eventName: "hbr-keyboard-grab", bubbles: true, composed: true })
	hbrKeyboardGrab: EventEmitter<{
		grabbed: boolean;
		id: string;
		element: HTMLElement;
		originalIndex: number;
	}>;

	/** Event emitted when keyboard move is requested */
	@Event({ eventName: "hbr-keyboard-move", bubbles: true, composed: true })
	hbrKeyboardMove: EventEmitter<{
		direction: "up" | "down" | "left" | "right";
		id: string;
		element: HTMLElement;
	}>;

	/** Event emitted when keyboard drop is confirmed */
	@Event({ eventName: "hbr-keyboard-drop", bubbles: true, composed: true })
	hbrKeyboardDrop: EventEmitter<{
		id: string;
		element: HTMLElement;
	}>;

	/** Emitted when the remove button is activated. */
	@Event({ eventName: "hbr-draggable-remove" })
	hbrDraggableRemove: EventEmitter<{
		id?: string;
		data?: string;
		element?: HTMLElement;
		event?: MouseEvent | KeyboardEvent;
	}>;

	private keyboardHandler: DraggableKeyboardHandler;

	/** Internal state to track if dragging is active (for overlay styling) */
	@State() private isDragging = false;

	/**
	 * Get the first slotted child element
	 */
	private get slottedChild(): HTMLElement | null {
		return this.host.firstElementChild as HTMLElement;
	}

	/**
	 * Computed property to determine if overlay should be shown.
	 */
	private get shouldoverlay(): boolean {
		return this.overlay;
	}

	private get shouldShowOverlayIcon(): boolean {
		return this.shouldoverlay && this.overlayIcon;
	}

	constructor() {
		// Initialize keyboard handler with context
		this.keyboardHandler = new DraggableKeyboardHandler({
			getHost: () => this.host,
			getSlottedChild: () => this.slottedChild,
			getDragId: () => this.dragId,
			emitters: {
				onKeyboardGrab: (detail) => this.hbrKeyboardGrab.emit(detail),
				onKeyboardMove: (detail) => this.hbrKeyboardMove.emit(detail),
				onKeyboardDrop: (detail) => this.hbrKeyboardDrop.emit(detail),
			},
		});
	}

	disconnectedCallback() {
		if (this.slottedChild) {
			removeGrabStateClasses(this.slottedChild);
		}
		this.keyboardHandler.reset();
	}

	private onDragStart = (event: DragEvent) => {
		// Only the innermost draggable that initiated the drag should handle it.
		// This prevents parent draggables in nested layouts from overwriting drag data.
		const sourceDraggable = event
			.composedPath()
			.find(
				(node): node is HTMLElement =>
					node instanceof HTMLElement &&
					node.tagName.toLowerCase() === "hbr-draggable",
			);
		if (sourceDraggable !== this.host) return;

		const parent = this.host.parentElement;
		const originalIndex = parent
			? Array.from(parent.children).indexOf(this.host)
			: -1;

		let parsedData = this.dragData;
		if (this.dragData) {
			try {
				parsedData = JSON.parse(this.dragData);
			} catch {
				parsedData = this.dragData;
			}
		}

		const dragInfo = {
			id: this.dragId,
			data: parsedData,
			originalIndex,
		};

		event.dataTransfer.setData("application/json", JSON.stringify(dragInfo));
		event.dataTransfer.setData("text/plain", this.dragData || this.dragId);

		const effectByOperation: Record<string, DataTransfer["effectAllowed"]> = {
			copy: "copy",
			move: "move",
			reorder: "move",
		};
		event.dataTransfer.effectAllowed =
			effectByOperation[this.operation] ?? "all";

		this.host.classList.add("dragging");

		if (this.slottedChild) {
			applyGrabStateClasses(this.slottedChild, {
				dragging: !this.overlay,
			});
		}

		this.hbrDragStart.emit({
			id: this.dragId,
			data: this.dragData,
			element: this.slottedChild,
		});

		setTimeout(() => {
			this.isDragging = true;
		}, 0);
	};

	private onDragEnd = (event: DragEvent) => {
		this.host.classList.remove("dragging");
		this.isDragging = false;

		if (this.slottedChild) {
			removeGrabStateClasses(this.slottedChild);
		}

		if (this.host.isConnected) {
			this.hbrDragEnd.emit({
				id: this.dragId,
				success: event.dataTransfer.dropEffect !== "none",
			});
		}
	};

	private onDeleteClick = (event: MouseEvent | KeyboardEvent) => {
		this.hbrDraggableRemove.emit({
			id: this.dragId,
			data: this.dragData,
			element: this.slottedChild,
			event,
		});
	};

	private onDeleteKeyDown = (event: KeyboardEvent) => {
		if (event.key === "Enter") {
			this.onDeleteClick(event);
		}
	};

	private stopDragFromDelete = (
		event: MouseEvent | PointerEvent | DragEvent,
	) => {
		event.stopPropagation();
		if ("preventDefault" in event) event.preventDefault();
	};

	render() {
		const customSystemIcons = getBootstrapConfig()?.systemIcons;
		return (
			<Host
				class={{
					dragging: this.isDragging,
				}}
				draggable="true"
				tabindex={0}
				role={DRAGGABLE_ARIA.role}
				aria-roledescription={DRAGGABLE_ARIA.roledescription}
				aria-grabbed={this.isDragging ? "true" : "false"}
				style={{
					cursor: this.isDragging ? "grabbing" : "grab",
				}}
				onDragStart={this.onDragStart}
				onDragEnd={this.onDragEnd}
				onKeyDown={this.keyboardHandler.onKeyDown}
			>
				<slot />
				<div class="drop-indicator" aria-hidden="true">
					<div class="drop-indicator__line" />
					<div class="drop-indicator__marker">
						<div class="drop-indicator__marker-dot" />
						<div class="drop-indicator__marker-icon" slot="invalid-icon">
							<hbr-tooltip
								content={this.i18n.rowFull}
								placement="top"
								open={true}
								exportparts="base:drop-indicator-invalid-tooltip, base__popup:drop-indicator-invalid-tooltip__popup, base__arrow:drop-indicator-invalid-tooltip__arrow"
							>
								<hbr-icon
									asset={
										customSystemIcons?.["status-negative"] || statusNegative
									}
									sentiment="danger"
									exportparts="base:drop-indicator-invalid-icon"
								/>
							</hbr-tooltip>
						</div>
					</div>
				</div>
				{this.shouldoverlay && (
					<div
						class={{
							overlay: true,
							"overlay--dragging": this.isDragging,
						}}
						part="overlay"
					>
						{this.shouldShowOverlayIcon && (
							<slot name="overlay-handle">
								<hbr-icon
									asset={customSystemIcons?.["dots-six"] || dotsSix}
									class="overlay__handle-icon"
									exportparts="base:overlay-handle"
								/>
							</slot>
						)}
					</div>
				)}

				{this.delete && (
					<slot name="delete-button">
						<hbr-button
							variant="outline"
							class="delete-button"
							arialabel="Delete item"
							exportparts="base:delete-button"
							onClick={this.onDeleteClick}
							onKeyDown={this.onDeleteKeyDown}
							onMouseDown={this.stopDragFromDelete}
							onPointerDown={this.stopDragFromDelete}
							onDragStart={this.stopDragFromDelete}
							sentiment="negative"
							size="small"
						>
							<hbr-icon
								asset={customSystemIcons?.["trash-simple"] || trashSimple}
								exportparts="base:delete-button-icon"
							/>
						</hbr-button>
					</slot>
				)}
			</Host>
		);
	}
}
